'use strict';
const assert = require('node:assert/strict');
const buildToggleDescriptor = require('./solution');

assert.equal(typeof buildToggleDescriptor, 'function');

const attributes = { 'data-count': 3, 'data-ready': true };
const click = () => 'clicked';
const handlers = { onClick: click, onMouseEnter() {} };
const options = {
  label: '', key: 0, prefix: 'switch',
  className: ' alpha  beta alpha\tbeta gamma ',
  active: 1, disabled: 0, expandable: true,
  attributes, handlers
};
const result = buildToggleDescriptor(options);
assert.deepEqual(result, {
  tag: 'button',
  key: 0,
  props: {
    className: 'switch alpha beta gamma switch-active',
    'data-count': 3,
    'data-ready': true,
    onClick: click,
    onMouseEnter: handlers.onMouseEnter,
    disabled: false
  },
  children: ['', { type: 'indicator', value: '›', side: 'end' }]
});
assert.equal(Object.getPrototypeOf(result), Object.prototype);

attributes['data-count'] = 99;
attributes['data-new'] = 'later';
handlers.onClick = () => 'changed';
handlers.onFocus = () => {};
options.label = 'changed';
assert.equal(result.props['data-count'], 3);
assert.equal(result.props['data-new'], undefined);
assert.equal(result.props.onClick, click);
assert.equal(result.props.onFocus, undefined);
assert.equal(result.children[0], '');

assert.deepEqual(buildToggleDescriptor({ label: 'Power' }), {
  tag: 'button', key: undefined,
  props: { className: 'toggle', disabled: false },
  children: ['Power']
});
assert.equal(buildToggleDescriptor({ label: 'X', key: null, disabled: true }).props.className,
  'toggle toggle-disabled');
assert.equal(buildToggleDescriptor({ label: 'X', active: true, disabled: true }).props.className,
  'toggle toggle-active toggle-disabled');

const badInputs = [null, [], {}, { label: 1 }, { label: 'x', key: {} },
  { label: 'x', prefix: 2 }, { label: 'x', className: null },
  { label: 'x', attributes: [] }, { label: 'x', attributes: { title: 'x' } },
  { label: 'x', attributes: { 'data-x': null } },
  { label: 'x', handlers: { onclick() {} } },
  { label: 'x', handlers: { onClick: true } }];
for (const input of badInputs) assert.throws(() => buildToggleDescriptor(input), TypeError);

const inheritedAttributes = Object.create({ 'data-x': 'inherited' });
inheritedAttributes['data-y'] = 'own';
const inheritedHandlers = Object.create({ onClick() {} });
inheritedHandlers.onFocus = () => {};
const ownOnly = buildToggleDescriptor({ label: 'x', attributes: inheritedAttributes, handlers: inheritedHandlers });
assert.equal(ownOnly.props['data-x'], undefined);
assert.equal(ownOnly.props.onClick, undefined);
assert.equal(ownOnly.props['data-y'], 'own');
assert.equal(typeof ownOnly.props.onFocus, 'function');

